// Static storage duration variables (various contexts):

// 1. Global/namespace scope (implicit static duration)
int global_var = 42;
namespace ns { int ns_var = 100; }

// 2. Local static (explicit static keyword)
void foo() {
    static int counter = 0;  // Initialized once, persists across calls
}

// 3. Class static member (declaration)
class Widget {
    static int instance_count;  // Declaration
};

// 4. Class static member (definition outside class)
int Widget::instance_count = 0;  // Definition with static duration

code_example:
#include <iostream>

class Logger {
public:
    Logger(const char* name) : name_(name) {
        std::cout << name_ << " constructed\n";
    }
    ~Logger() {
        std::cout << name_ << " destroyed\n";
    }
private:
    const char* name_;
};

// 1. Global static duration (implicit)
Logger global_logger("GlobalLogger");

// 2. Class static member (shared across instances)
class Counter {
public:
    static int total_count;  // Declaration

    Counter() { ++total_count; }
    ~Counter() { --total_count; }
};

int Counter::total_count = 0;  // Definition (static duration)

// 3. Local static (initialized on first call)
int& get_id() {
    static int next_id = 1000;  // Initialized once, persists
    return next_id;
}

// 4. Side effects prevent elimination
static Logger unused_logger("UnusedLogger");  // MUST NOT be eliminated!
// Even though unused_logger is never referenced, its constructor
// and destructor have observable side effects (output), so the
// compiler is forbidden from optimizing it away.

int main() {
    std::cout << "main() started\n";

    // Local static initialized on first use
    std::cout << "First ID: " << get_id()++ << "\n";
    std::cout << "Second ID: " << get_id()++ << "\n";

    // Class static member
    Counter c1, c2;
    std::cout << "Total counters: " << Counter::total_count << "\n";

    std::cout << "main() ending\n";
    return 0;
}

// Destruction order: reverse of initialization
// Output:
// GlobalLogger constructed
// UnusedLogger constructed     <- Side effects preserve this
// main() started
// First ID: 1000
// Second ID: 1001
// Total counters: 2
// main() ending
// UnusedLogger destroyed        <- Destroyed even though "unused"
// GlobalLogger destroyed
